Instead of focusing on full matrices computation, we consider approximating
\begin{equation} z = \left(\sum_{i=1}^{n}\nabla_y^2g_i(x,y^*(x))\right)^{-1}\left(\sum_{i=1}^{n}\nabla_yf_i(x,y^*(x))\right).
\end{equation}

Suppose each agent only has access to $H_i\in\mathbb{S}_{++}^{q\times q}$ and $b_i\in\mathbb{R}^q$, and all the agents collectively solve for
\begin{equation} \sum_{i=1}^{n}H_iz = \sum_{i=1}^{n}b_i,\ \text{or } z = \left(\sum_{i=1}^{n}H_i\right)^{-1}\left(\sum_{i=1}^{n}b_i\right).
\end{equation}

From an optimization perspective, the above expression is the optimality condition of:
\begin{equation} \min_{z\in\mathbb{R}^{q}}\frac{1}{n}\sum_{i=1}^{n}h_i(z),\ \text{where  }h_i(z)=\frac{1}{2}z^{\top}H_iz - b_i^{\top} z.
\end{equation}

\caption{Hessian-Inverse-Gradient Product oracle} \begin{algorithmic}[1]
        \STATE {\bfseries Input:} $(H_{i,t}^{(k)}, b_{i,t}^{(k)})$, for $0\leq t\leq N$ accessible only to agent $i$. Stepsize $\gamma$, iteration number $N$, $d_{i,0}^{(k)} = -b_{i,0}^{(k)},\ s_{i,0}^{(k)} = - b_{i,0}^{(k)},\ \text{and } z_{i,0}^{(k)} = 0$

        \FOR{$t=0,1,...,N-1$}
            \FOR{$i=1,...,n$}
                \STATE $z_{i,t+1}^{(k)} = \sum_{j=1}^{n}w_{ij}z_{j,t}^{(k)} - \gamma d_{i,t}^{(k)}$, \\
                \STATE $s_{i,t+1}^{(k)} = H_{i,t+1}^{(k)}z_{i,t+1}^{(k)}- b_{i,t+1}^{(k)}$, \\
                \STATE $d_{i,t+1}^{(k)} =\sum_{j=1}^{n}w_{ij}d_{j,t}^{(k)} + s_{i,t+1}^{(k)} - s_{i,t}^{(k)}$
            \ENDFOR
        \ENDFOR
        \STATE {\bfseries Output:}{$z_{i,N}^{(k)} $ on each node.}
    \end{algorithmic}

Suppose Assumptions \ref{assump: lip_convexity}, \ref{assump: W}, \ref{assump: similarity_of_g}, and \ref{assump: stoc_derivatives} hold. There exist constants \footnote{The constants are independent of $K$ and the details are given in the appendix.} $0<c_1<c_2$ such that in Algorithm \ref{algo:DSBO} if we set $\gamma\in (c_1, c_2)$, $T\geq 1$, and
    \begin{align*}
        \alpha_k \equiv \Theta\left(\frac{1}{\sqrt{K}}\right),\ \beta_k \equiv \Theta\left(\frac{1}{\sqrt{K}}\right),\ N = \Theta\left(\log K\right), 
    \end{align*}
    then we have
    \[
        \begin{aligned}
            \min_{0\leq k\leq K}\mathbb{E}\left[\|\nabla\Phi(\bar{x}_k)\|^2\right] &= \mathcal{O}\left(\frac{1}{\sqrt{K}}\right), \\
            \min_{0\leq k\leq K}\frac{\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}_n\|^2\right]}{n} &= \mathcal{O}\left(\frac{1}{K}\right).
        \end{aligned}
    \]

