nodes.statement:
Note that our algorithm can be used to solve Decentralized Stochastic Compositional Optimization (DSCO) problem:
\begin{equation} \min_{x\in\mathbb{R}^p}\quad \Phi(x) = \frac{1}{n}\sum_{i=1}^{n}f_i\left(\frac{1}{n}\sum_{j=1}^{n}g_j(x)\right),
\end{equation}
which can be written in a bilevel formulation:
\begin{equation} \begin{aligned}
        \min_{x\in\mathbb{R}^p}\quad \Phi(x) &= \frac{1}{n}\sum_{i=1}^{n}f_i(y^*(x)) \\
        \text{s.t.}\quad y^*(x) &= arg\,min_{y\in\mathbb{R}^{q}}\frac{1}{n}\sum_{i=1}^{n}\left(\frac{1}{2}y^{\top} y - g_i(x)^{\top} y\right),
    \end{aligned}
\end{equation}

\begin{aligned}
        \min_{x\in\mathbb{R}^p}\quad \Phi(x) &= \frac{1}{n}\sum_{i=1}^{n}f_i(y^*(x)) \\
        \text{s.t.}\quad y^*(x) &= arg\,min_{y\in\mathbb{R}^{q}}\frac{1}{n}\sum_{i=1}^{n}\left(\frac{1}{2}y^{\top} y - g_i(x)^{\top} y\right),
    \end{aligned}

In this section we study the applications of Algorithm \ref{algo:DSBO} on hyperparameter optimization:
\begin{align*}
    &\min_{\lambda\in\mathbb{R}^p}\quad  \frac{1}{n}\sum_{i=1}^{n}f_i(\lambda,\omega^*(\lambda)), \\
    &\text{s.t.}\quad \omega^*(\lambda) =arg\,min_{w\in\mathbb{R}^q} \frac{1}{n}\sum_{i=1}^{n}g_i(\lambda,\omega),
\end{align*}
where we aim at finding the optimal hyperparameter $\lambda$ under the constraint that $\omega^*(\lambda)$ is the optimal model parameter given $\lambda$.

Suppose Assumptions \ref{assump: lip_convexity} and \ref{assump: stoc_derivatives} hold, we know $\nabla\Phi(x)$ and $y^*(x)$ defined in \eqref{eq: dsbo_opt} are $L_{\Phi}$ and $L_{y^*}$-Lipschitz continuous respectively with the constants given by
    \begin{equation} L_{\Phi} = L_{f,1} + \frac{2L_{f,1}L_{g,1} + L_{g,2}L_{f,0}^2 }{\mu_g} + \frac{2L_{g,1}L_{f,0}L_{g,2}+L_{g,1}^2L_{f,1}}{\mu_g^2} + \frac{L_{g,2}L_{g,1}^2L_{f,0}}{\mu_g^3},\ L_{y^*} = \frac{L_{g,1}}{\mu_g}.
    \end{equation}

Suppose we are given matrices $A_i$ and vectors $b_i$ such that there exist $0<\mu<L$ such that $\mu I\preceq A_i\preceq LI$ for $1\leq i\leq n$. $W = (w_{ij})$ satisfies Assumption \ref{assump: W}. The sequences $\{x_{i,k}\},\ \{s_{i,k}\}$ and $\{v_{i,k}\}$ satisfy for any $k\geq 0$ and $1\leq i\leq n$,
    \begin{align*}
        &x_{i,k+1} = \sum_{j=1}^{n}w_{ij}x_{j,k} - \alpha s_{i,k},\ s_{i,k+1} = \sum_{j=1}^{n}w_{ij}s_{j,k} +v_{i,k+1} - v_{i,k},\ v_{i,k} = A_{i,k}x_{i,k} - b_{i,k},\ s_{i,0} = v_{i,0}, \\
        &\mathbb{E}\left[A_{i,k}\right] = A_i,\ \mathbb{E}\left[b_{i,k}\right] = b_i,\ \mathbb{E}\left[\|A_{i,k} - A_i\|^2\right]\leq \sigma_1^2,\ \mathbb{E}\left[\|b_{i,k} - b_i\|^2\right]\leq \sigma_2^2.
    \end{align*}
    Moreover, we assume $A_{i,k}, x_{j,k}, b_{i,k}$ are independent for any $i,j\in\left\{1,...,n\right\}$, $\left\{A_{i,k}\right\}_{i=1}^{n}$ are independent and $\left\{b_{i,k}\right\}_{i=1}^{n}$ are independent. Define
    \begin{align*}
        &\tilde{\sigma}_1^2 = \sigma_1^2 + L^2,\ \tilde{\sigma}_2^2 = \sigma_2^2 + \max_i\|b_i\|^2,\ x^* := \left(\frac{1}{n}\sum_{i=1}^{n}A_i\right)^{-1}\left(\frac{1}{n}\sum_{i=1}^{n}b_i\right), \\
        &C_1 = 9\sigma_1^2 + 6\alpha^2\tilde{\sigma}_1^2 + \frac{18\alpha^2\sigma_1^2\tilde{\sigma}_1^2}{n},\ C_2 = 12\tilde{\sigma}_1^2 + 9\sigma_1^2 + 12\alpha^2L^2\tilde{\sigma}_1^2  + \frac{18\alpha^2\sigma_1^2\tilde{\sigma}_1^2}{n}, \\
        &C_3 = 6\rho^2\tilde{\sigma}_1^2,\ C_4 = 2\sigma_2^2 + \frac{6\alpha^2\sigma_2^2\tilde{\sigma}_1^2}{n} + \left(9\sigma_1^2 + \frac{18\alpha^2\sigma_1^2\tilde{\sigma}_1^2}{n}\right)\|x^*\|^2, \\
        &c = \left(\frac{\alpha^2}{n}(3\sigma_1^2\|x^*\|^2 + \sigma_2^2),\ 0,\ \frac{(1+\rho^2)}{1-\rho^2}C_4\right)^{\top},\ M = 
        \begin{pmatrix}
            M_{11} &M_{12} &0 \\
            0 &M_{22} &M_{23} \\
            M_{31} &M_{32} &M_{33}
        \end{pmatrix}, \\
        & M_{11} = 1-\alpha\mu,\ M_{12} = \left(\frac{2\alpha}{\mu} + 2\alpha^2\right)\tilde{\sigma}_1^2,\ M_{22} = \frac{1+\rho^2}{2},\ M_{23} = \alpha^2\frac{1+\rho^2}{1-\rho^2} \\
        &M_{31} = \frac{1+\rho^2}{1-\rho^2}C_1,\ M_{32} = \frac{1+\rho^2}{1-\rho^2}C_2,\ M_{33} = \frac{1+\rho^2}{2} + \frac{1+\rho^2}{1-\rho^2}C_3\alpha^2.
    \end{align*}
    If $\alpha$ satisfies
    \begin{equation} \begin{aligned}
            &\left(1+\frac{\alpha\mu}{2}\right)(1-\alpha\mu)^2 + \frac{3\alpha^2\sigma_1^2}{n}<1-\alpha\mu,\ 0< \alpha_1\leq \alpha \leq \alpha_2 \text{ for some } 0<\alpha_1<\alpha_2, \\
            &\rho(M) < 1 - \frac{2\alpha\mu}{3},\ \text{ and }~M~\text{has 3 different positive eigenvalues,}  
        \end{aligned}
    \end{equation} 
    then we have
    \begin{align} \begin{aligned}
            \mathbb{E}\left[\|\bar{x}_{k+1} - x^*\|^2\right] &\leq (1-\alpha\mu)\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \left(\frac{2\alpha}{\mu} + 2\alpha^2\right)\frac{\tilde{\sigma}_1^2}{n}\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2\right]\\&\qquad + \frac{\alpha^2}{n}(3\sigma_1^2\|x^*\|^2 + \sigma_2^2), \\
        \|X_{k+1} - \bar{x}_{k+1}\mathbf{1}^{\top}\|^2 &\leq \frac{(1+\rho^2)}{2}\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2 + \alpha^2\frac{1+\rho^2}{1-\rho^2}\|S_k - \bar{s}_k\mathbf{1}^{\top}\|^2, \\
        \mathbb{E}\left[\frac{\|S_{k+1} - \bar{s}_{k+1}\mathbf{1}^{\top}\|^2}{n}\right] &\leq  \frac{1+\rho^2}{1-\rho^2}C_1\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \frac{1+\rho^2}{1-\rho^2}C_2\mathbb{E}\left[\frac{\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2}{n}\right]  \\&\qquad \qquad + \left(\frac{1+\rho^2}{2}  + \frac{1+\rho^2}{1-\rho^2}C_3\alpha^2\right)\mathbb{E}\left[\frac{\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2}{n}\right] +\frac{1+\rho^2}{1-\rho^2}C_4.
        \end{aligned}
    \end{align}
    Moreover, we set $P$ such that $M = P\cdot\text{diag}(\lambda_1, \lambda_2, \lambda_3)P^{-1}$ with $0<\lambda_3<\lambda_2<\lambda_1$ being eigenvalues and each column of $P$ is a unit vector. Define $C_M:= \|P\|_2\|P^{-1}\|_2$, we have
    \begin{align}
        &\max\left(\frac{1}{n}\mathbb{E}\left[\|X_k - x^*\mathbf{1}^{\top}\|^2\right], \frac{1}{n}\mathbb{E}\left[\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2\right]\right) \notag \\
        \leq &3C_M\left(1-\frac{2\alpha\mu}{3}\right)^k\left(\mathbb{E}\left[\|\bar{x}_0 - x^*\|^2\right] + \mathbb{E}\left[\frac{\|X_0\|^2 + \|S_0\|^2}{n}\right]\right) + \frac{5C_M\|c\|}{\alpha\mu}, \\
        &\frac{1}{n}\mathbb{E}\left[\|X_k\|^2\right]\leq 6C_M\left(1-\frac{2\alpha\mu}{3}\right)^k\left(\mathbb{E}\left[\|\bar{x}_0 - x^*\|^2\right] + \mathbb{E}\left[\frac{\|X_0\|^2 + \|S_0\|^2}{n}\right]\right) + \frac{10C_M\|c\|}{\alpha\mu} + 2\|x^*\|^2. \end{align}

\begin{aligned}
            &\left(1+\frac{\alpha\mu}{2}\right)(1-\alpha\mu)^2 + \frac{3\alpha^2\sigma_1^2}{n}<1-\alpha\mu,\ 0< \alpha_1\leq \alpha \leq \alpha_2 \text{ for some } 0<\alpha_1<\alpha_2, \\
            &\rho(M) < 1 - \frac{2\alpha\mu}{3},\ \text{ and }~M~\text{has 3 different positive eigenvalues,}  
        \end{aligned}

\begin{aligned}
            \mathbb{E}\left[\|\bar{x}_{k+1} - x^*\|^2\right] &\leq (1-\alpha\mu)\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \left(\frac{2\alpha}{\mu} + 2\alpha^2\right)\frac{\tilde{\sigma}_1^2}{n}\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2\right]\\&\qquad + \frac{\alpha^2}{n}(3\sigma_1^2\|x^*\|^2 + \sigma_2^2), \\
        \|X_{k+1} - \bar{x}_{k+1}\mathbf{1}^{\top}\|^2 &\leq \frac{(1+\rho^2)}{2}\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2 + \alpha^2\frac{1+\rho^2}{1-\rho^2}\|S_k - \bar{s}_k\mathbf{1}^{\top}\|^2, \\
        \mathbb{E}\left[\frac{\|S_{k+1} - \bar{s}_{k+1}\mathbf{1}^{\top}\|^2}{n}\right] &\leq  \frac{1+\rho^2}{1-\rho^2}C_1\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \frac{1+\rho^2}{1-\rho^2}C_2\mathbb{E}\left[\frac{\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2}{n}\right]  \\&\qquad \qquad + \left(\frac{1+\rho^2}{2}  + \frac{1+\rho^2}{1-\rho^2}C_3\alpha^2\right)\mathbb{E}\left[\frac{\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2}{n}\right] +\frac{1+\rho^2}{1-\rho^2}C_4.
        \end{aligned}

Note that by definition of $\tilde{\sigma}_1^2$ and $\tilde{\sigma}_2^2$ we have
    \begin{equation} \begin{aligned}
            &\mathbb{E}\left[\|A_{i,k}\|^2\right] = \mathbb{E}\left[\|A_{i,k}-A_i\|^2\right] + \|A_i\|_2^2\leq \sigma_1^2 + L^2 = \tilde{\sigma}_1^2,\\
            &\mathbb{E}\left[\|b_{i,k}\|^2\right] = \mathbb{E}\left[\|b_{i,k}-b_i\|^2\right] + \|b_i\|^2 \leq \sigma_2^2 + \max_i\|b_i\|^2 = \tilde{\sigma}_2^2.
        \end{aligned}
    \end{equation}
    By $s_{i,0} = v_{i,0}$ we know $\bar{s}_0 = \bar{v}_0$. From the recursion we know
    \[
        \bar{s}_{k+1} = \bar{s}_k + \bar{v}_{k+1} - \bar{v}_k,
    \]
    and hence $\bar{s}_k = \bar{v}_k$ by induction. For $\bar{x}_k$ we know
    \begin{align*}
        &\bar{x}_{k+1} - x^* \\
        = &\bar{x}_k - x^* - \frac{\alpha}{n}\sum_{i=1}^{n}(A_{i,k}x_{i,k} - b_{i,k}) \\
        = &\bar{x}_k - x^* - \frac{\alpha}{n}\sum_{i=1}^{n}(A_i\bar{x}_k - b_i) + \frac{\alpha}{n}\sum_{i=1}^{n}(A_i\bar{x}_k - b_i) - \frac{\alpha}{n}\sum_{i=1}^{n}(A_{i,k}x_{i,k} - b_{i,k}) \\
        = &\left(I - \frac{\alpha}{n}\sum_{i=1}^{n}A_i\right)(\bar{x}_k - x^*) + \frac{\alpha}{n}\sum_{i=1}^{n}A_{i,k}(\bar{x}_k - x_{i,k}) + \frac{\alpha}{n}\sum_{i=1}^{n}((A_i - A_{i,k})\bar{x}_k + b_{i,k} - b_i).
    \end{align*}
    Using the above equality, $\mathbb{E}\left[A_{i,k}\right] = A_i$ and $\mathbb{E}\left[b_{i,k}\right] = b_i$, we know
    \begin{align*}
        &\mathbb{E}\left[\|\bar{x}_{k+1} - x^*\|^2\right] \\
        = &\mathbb{E}\left[\|\left(I - \frac{\alpha}{n}\sum_{i=1}^{n}A_i\right)(\bar{x}_k - x^*) + \frac{\alpha}{n}\sum_{i=1}^{n}A_{i,k}(\bar{x}_k - x_{i,k})\|^2\right] + \frac{\alpha^2}{n^2}\mathbb{E}\left[\|\sum_{i=1}^{n}((A_i - A_{i,k})\bar{x}_k + b_{i,k} - b_i)\|^2\right] \\
        + &\mathbb{E}\left[\<\left(I - \frac{\alpha}{n}\sum_{i=1}^{n}A_i\right)(\bar{x}_k - x^*) + \frac{\alpha}{n}\sum_{i=1}^{n}A_{i,k}(\bar{x}_k - x_{i,k}), \frac{\alpha}{n}\sum_{i=1}^{n}((A_i - A_{i,k})\bar{x}_k + b_{i,k} - b_i)> \right] \\
        \leq &\left(1+\frac{\alpha\mu}{2}\right)(1-\alpha\mu)^2\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \left(1+\frac{2}{\alpha\mu}\right)\frac{\alpha^2\tilde{\sigma}_1^2}{n}\sum_{i=1}^{n}\mathbb{E}\left[\|\bar{x}_k - x_{i,k}\|^2\right] + \frac{\alpha^2}{n^2}(n\sigma_1^2\mathbb{E}\left[\|\bar{x}_k\|^2\right] + n\sigma_2^2) \\

        + & \frac{\alpha^2}{2n^2}\sum_{i=1}^{n}\mathbb{E}\left[\sigma_1^2\|\bar{x}_k\|^2 + \tilde{\sigma}_1^2\|\bar{x}_k - x_{i,k}\|^2\right] \\
        = &\left(1+\frac{\alpha\mu}{2}\right)(1-\alpha\mu)^2\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \left(\frac{2\alpha}{\mu} + \alpha^2 + \frac{\alpha^2}{2n}\right)\frac{\tilde{\sigma}_1^2}{n}\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2\right] + \frac{\alpha^2}{n}\left(\frac{3\sigma_1^2}{2}\mathbb{E}\left[\|\bar{x}_k\|^2\right] + \sigma_2^2\right) \\
        \leq &\left[\left(1+\frac{\alpha\mu}{2}\right)(1-\alpha\mu)^2 + \frac{3\alpha^2\sigma_1^2}{n}\right]\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \left(\frac{2\alpha}{\mu} + 2\alpha^2\right)\frac{\tilde{\sigma}_1^2}{n}\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2\right] + \frac{\alpha^2}{n}(3\sigma_1^2\|x^*\|^2 + \sigma_2^2) \\
        \leq & (1-\alpha\mu)\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \left(\frac{2\alpha}{\mu} + 2\alpha^2\right)\frac{\tilde{\sigma}_1^2}{n}\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2\right] + \frac{\alpha^2}{n}(3\sigma_1^2\|x^*\|^2 + \sigma_2^2).
    \end{align*}
    The first inequality holds because we have
    \begin{align*}
        &\mathbb{E}\left[\<\left(I - \frac{\alpha}{n}\sum_{i=1}^{n}A_i\right)(\bar{x}_k - x^*) + \frac{\alpha}{n}\sum_{i=1}^{n}A_{i,k}(\bar{x}_k - x_{i,k}), \frac{\alpha}{n}\sum_{i=1}^{n}((A_i - A_{i,k})\bar{x}_k + b_{i,k} - b_i)> \right] \\
        = &\mathbb{E}\left[\<\frac{\alpha}{n}\sum_{i=1}^{n}A_{i,k}(\bar{x}_k - x_{i,k}), \frac{\alpha}{n}\sum_{i=1}^{n}((A_i - A_{i,k})\bar{x}_k + b_{i,k} - b_i)> \right] \\
        =& \mathbb{E}\left[\< \frac{\alpha}{n}\sum_{i=1}^{n}A_{i,k}(\bar{x}_k - x_{i,k}), \frac{\alpha}{n}\sum_{i=1}^{n}(A_i - A_{i,k})\bar{x}_k> \right] \\
        = & \frac{\alpha^2}{n^2}\sum_{i=1}^{n}\mathbb{E}\left[(\bar{x}_k - x_{i,k})^{\top} A_{i,k}^{\top}(A_i-A_{i,k})\bar{x}_k\right] \leq \frac{\alpha^2}{2n^2}\sum_{i=1}^{n}\mathbb{E}\left[\sigma_1^2\|\bar{x}_k\|^2 + \tilde{\sigma}_1^2\|\bar{x}_k - x_{i,k}\|^2\right],
    \end{align*}
    the second inequality uses $\|\bar{x}_k\|^2\leq 2\|\bar{x}_k - x^*\|^2 + 2\|x^*\|^2$, and the third inequality uses \eqref{ineq: stepsize_for_quadratics}. For $\|X_{k+1} - \bar{x}_{k+1}\mathbf{1}^{\top}\|^2$ we know
    \begin{equation} \begin{aligned}
            &\|X_{k+1} - \bar{x}_{k+1}\mathbf{1}^{\top}\|^2 = \|X_kW - \bar{x}_k\mathbf{1}^{\top} - \alpha (S_k - \bar{s}_k\mathbf{1}^{\top})\|^2\\
        \leq &\left(1 + \frac{1-\rho^2}{2\rho^2}\right)\rho^2\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2 + \left(1 + \frac{2\rho^2}{1-\rho^2}\right)\alpha^2\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2.
        \end{aligned}
    \end{equation}
    The inequality uses Cauchy-Schwarz inequality and the fact that 
    \begin{align*}
        &\|X_kW - \bar{x}_k\mathbf{1}^{\top}\| = \|\left(X_k - \bar{x}_k\mathbf{1}^{\top}\right)\left(W - \frac{\mathbf{1}\mathbf{1}^{\top}}{n}\right)\| = \|\left(W - \frac{\mathbf{1}\mathbf{1}^{\top}}{n}\right)\left(X_k - \bar{x}_k\mathbf{1}^{\top}\right)^{\top}\|\\
        \leq &\|W - \frac{\mathbf{1}\mathbf{1}^{\top}}{n}\|_2\|X_k - \bar{x}_k\mathbf{1}^{\top}\|\leq \rho\|X_k - \bar{x}_k\mathbf{1}^{\top}\|,
    \end{align*}
    where the last inequality uses Assumption \ref{assump: W}. For $\|S_{k} - \bar{s}_{k}\mathbf{1}^{\top}\|^2$ we know
    \begin{equation} \begin{aligned}
            & \|S_{k+1} - \bar{s}_{k+1}\mathbf{1}^{\top}\|^2 = \|S_kW - \bar{s}_k\mathbf{1}^{\top} + V_{k+1} - V_k - \bar{v}_{k+1}\mathbf{1}^{\top} + \bar{v}_k\mathbf{1}^{\top}\|^2 \\
        \leq &\left(1 + \frac{1-\rho^2}{2\rho^2}\right)\|S_k - \bar{s}_k\mathbf{1}^{\top}\|^2 + \left(1 + \frac{2\rho^2}{1-\rho^2}\right)\|\left(V_{k+1}-V_k\right)\left(I - \frac{\mathbf{1}\mathbf{1}^{\top}}{n}\right)\|^2 \\
        = &\frac{1+\rho^2}{2}\|S_k - \bar{s}_k\mathbf{1}^{\top}\|^2 + \frac{1+\rho^2}{1-\rho^2}\|V_{k+1} - V_k\|^2.
        \end{aligned}
    \end{equation}
    For $V_{k+1} - V_k$ we have
    \begin{align*}
        &\mathbb{E}\left[\|V_{k+1} - V_k\|^2\right] \\
        = &\sum_{i=1}^{n}\mathbb{E}\left[\|A_{i,k+1}(x_{i,k+1} - x_{i,k}) + (A_{i,k+1} - A_i + A_i - A_{i,k})x_{i,k} +(b_{i,k} - b_i + b_i - b_{i,k+1})\|^2\right] \\
        = &\sum_{i=1}^{n}\mathbb{E}\left[\|A_{i,k+1}(x_{i,k+1} - x_{i,k}) + (A_{i,k+1} - A_i)x_{i,k}\|^2 + \|(A_i - A_{i,k})x_{i,k}\|^2 + \|b_{i,k} - b_i\|^2 + \|b_i - b_{i,k+1}\|^2\right] \\
        \leq &\sum_{i=1}^{n}\mathbb{E}\left[2\|A_{i,k+1}(x_{i,k+1} - x_{i,k})\|^2 + 2\|(A_{i,k+1} - A_i)x_{i,k}\|^2 + \|(A_i - A_{i,k})x_{i,k}\|^2 + \|b_{i,k} - b_i\|^2 + \|b_i - b_{i,k+1}\|^2\right] \\
        \leq &2\tilde{\sigma}_1^2\mathbb{E}\left[\|X_{k+1}-X_k\|^2\right] + 3\sigma_1^2\mathbb{E}\left[\|X_k\|^2\right] + 2n\sigma_2^2.
    \end{align*}
    For $\|X_{k+1} - X_k\|$ we know
    \begin{align*}
        &\mathbb{E}\left[\|X_{k+1} - X_k\|^2\right] = \mathbb{E}\left[\|X_kW - X_k - \alpha S_kW\|^2\right]\\
        = &\mathbb{E}\left[\|\left(X_k - \bar{x}_k\mathbf{1}^{\top}\right)(W - I) - \alpha (S_kW - \bar{s}_k\mathbf{1}^{\top}) - \alpha\bar{s}_k\mathbf{1}^{\top}\|^2\right] \\
        \leq &3\|W - I\|_2^2\mathbb{E}\left[\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2\right] + 3\alpha^2\rho^2\mathbb{E}\left[\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2\right] + 3n\alpha^2\mathbb{E}\left[\|\bar{s}_k\|^2\right] \\
        \leq &6\mathbb{E}\left[\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2\right] + 3\alpha^2\rho^2\mathbb{E}\left[\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2\right] \\&\qquad\qquad + 3\alpha^2(\frac{\sigma_1^2}{n}\mathbb{E}\left[\|X_k\|^2\right] + \sigma_2^2 + 2L^2\mathbb{E}\left[\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2 + n\|\bar{x}_k-x^*\|^2\right]) \\
        = & (6 + 6\alpha^2L^2)\mathbb{E}\left[\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2\right] + 3\alpha^2\rho^2\mathbb{E}\left[\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2\right] + \frac{3\alpha^2\sigma_1^2}{n}\mathbb{E}\left[\|X_k\|^2\right] \\
        &\qquad \qquad+ 3n\alpha^2\mathbb{E}\left[\|\bar{x}_k-x^*\|^2\right] + 3\alpha^2\sigma_2^2,
    \end{align*}
    where the second inequality holds since
    \begin{align*}
        &\mathbb{E}\left[\|\bar{s}_k\|^2\right] = \mathbb{E}\left[\|\frac{1}{n}\sum_{i=1}^{n}(A_{i,k}x_{i,k} - b_{i,k})\|^2\right] \\
        = &\mathbb{E}\left[\|\frac{1}{n}\sum_{i=1}^{n}((A_{i,k} - A_i)x_{i,k} - (b_{i,k} - b_i)) + \frac{1}{n}\sum_{i=1}^{n}(A_ix_{i,k} - A_i\bar{x}_k) + \frac{1}{n}\sum_{i=1}^{n}A_i(\bar{x}_k - x^*)\|^2\right] \\
        = &\frac{1}{n^2}\sum_{i=1}^{n}\mathbb{E}\left[\|(A_{i,k} - A_i)x_{i,k}\|^2 + \|b_{i,k}-b_i\|^2\right] + \frac{1}{n^2}\mathbb{E}\left[\|\sum_{i=1}^{n}((A_ix_{i,k} - A_i\bar{x}_k) + A_i(\bar{x}_k - x^*))\|^2\right]\\
        \leq & \frac{\sigma_1^2}{n^2}\mathbb{E}\left[\|X_k\|^2\right] + \frac{\sigma_2^2}{n} + \frac{2L^2}{n}\mathbb{E}\left[\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2 + n\|\bar{x}_k-x^*\|^2\right].
    \end{align*}
    Hence we know
    \begin{align*}
        &\mathbb{E}\left[\|V_{k+1} - V_k\|^2\right] \leq 2\tilde{\sigma}_1^2\mathbb{E}\left[\|X_{k+1}-X_k\|^2\right] + 3\sigma_1^2\mathbb{E}\left[\|X_k\|^2\right] + 2n\sigma_2^2\\
        \leq &2\tilde{\sigma}_1^2\left\{(6 + 6\alpha^2L^2)\mathbb{E}\left[\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2\right] + 3\alpha^2\rho^2\mathbb{E}\left[\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2\right] + 3n\alpha^2\mathbb{E}\left[\|\bar{x}_k-x^*\|^2\right]\right\} \\
        + &\left(3\sigma_1^2 + \frac{6\alpha^2\sigma_1^2\tilde{\sigma}_1^2}{n}\right)\mathbb{E}\left[\|X_k\|^2\right] + (2n\sigma_2^2 + 6\alpha^2\sigma_2^2\tilde{\sigma}_1^2) \\
        \leq &nC_1\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + C_2\mathbb{E}\left[\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2\right] + \alpha^2C_3\mathbb{E}\left[\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2\right] + nC_4,
    \end{align*}
    where the second inequality uses 
    \begin{align*}
        \|X_k\|^2\leq 3\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2 + n\|\bar{x}_k - x^*\|^2 + n\|x^*\|^2\right].
    \end{align*}
    The above inequalities and \eqref{ineq: S_cons_onestep} imply
    \begin{equation}
        \begin{aligned}
            &\frac{1}{n}\mathbb{E}\left[\|S_{k+1} - \bar{s}_{k+1}\mathbf{1}^{\top}\|^2\right]\\
            \leq &\frac{1+\rho^2}{2n}\|S_k - \bar{s}_k\mathbf{1}^{\top}\|^2 + \frac{1+\rho^2}{1-\rho^2}
            \left(C_1\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + C_2\mathbb{E}\left[\frac{\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2}{n}\right] + \alpha^2C_3\mathbb{E}\left[\frac{\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2}{n}\right] + C_4\right) \\
            \leq &\frac{1+\rho^2}{1-\rho^2}C_1\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \frac{1+\rho^2}{1-\rho^2}C_2\mathbb{E}\left[\frac{\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2}{n}\right] + \left(\frac{1+\rho^2}{2} + \frac{1+\rho^2}{1-\rho^2}C_3\alpha^2\right)\mathbb{E}\left[\frac{\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2}{n}\right] +\frac{1+\rho^2}{1-\rho^2}C_4.

        \end{aligned}
    \end{equation}
    Now if we define
    \begin{align*}
        &\Gamma_k = \left(\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right],\ \mathbb{E}\left[\frac{\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2}{n}\right],\ \mathbb{E}\left[\frac{\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2}{n}\right]\right)^{\top},\ \\
        &c = \left(\frac{\alpha^2}{n}(3\sigma_1^2\|x^*\|^2 + \sigma_2^2),\ 0,\ \frac{(1+\rho^2)}{1-\rho^2}C_4\right)^{\top},\ M = 
        \begin{pmatrix}
            M_{11} &M_{12} &0 \\
            0 &M_{22} &M_{23} \\
            M_{31} &M_{32} &M_{33}
        \end{pmatrix}, \\
        & M_{11} = 1-\alpha\mu,\ M_{12} = \left(\frac{2\alpha}{\mu} + 2\alpha^2\right)\tilde{\sigma}_1^2,\ M_{22} = \frac{1+\rho^2}{2},\ M_{23} = \alpha^2\frac{1+\rho^2}{1-\rho^2} \\
        &M_{31} = \frac{1+\rho^2}{1-\rho^2}C_1,\ M_{32} = \frac{1+\rho^2}{1-\rho^2}C_2,\ M_{33} = \frac{1+\rho^2}{2} + \frac{1+\rho^2}{1-\rho^2}C_3\alpha^2,
    \end{align*}
    then by \eqref{ineq: dsgd_quadratic} we know $\Gamma_{i+1}\leq M\Gamma_i + c$ for any $i$, and thus 
    \[
        \Gamma_{k+1}\leq M\Gamma_k + c\leq...\leq M^{k+1}\Gamma_0 +\sum_{i=0}^{k}M^ic,
    \]
    where all the inequalities are element-wise. By \eqref{ineq: stepsize_for_quadratics} we know there exists an invertible matrix $P\in \mathbb{R}^{3\times 3}$ such that $M = P\cdot\text{diag}(\lambda_1, \lambda_2, \lambda_3)P^{-1}$, and $0<\lambda_3<\lambda_2<\lambda_1<1-\frac{2\alpha\mu}{3}$. Without loss of generality we may assume each column of $P$ (as an eigenvector) is a unit vector. Hence we know
    \begin{equation} \|M^k\|_2 = \|P\cdot \text{diag}(\lambda_1^k, \lambda_2^k,\lambda_3^k)P^{-1}\|_2\leq \left(1-\frac{2\alpha\mu}{3}\right)^k\|P\|_2\|P^{-1}\|_2 = C_M\cdot \left(1-\frac{2\alpha\mu}{3}\right)^k,
    \end{equation}
    where we define $C_M := \|P\|_2\|P^{-1}\|_2$ in the last equality. Note that since we choose $P$ such that each column is a unit vector and $M = P\cdot\text{diag}(\lambda_1, \lambda_2, \lambda_3)P^{-1}$, $P$ is uniquely determined and $C_M$ is a continuous function of $\alpha$ and other constants $(\sigma_1,\ \sigma_2,\ \mu,\ L,\ \max_{i}\|b_i\|,\ \|x^*\|,\ n,\ \rho)$. On the other hand, observe that 
    \begin{align} \begin{aligned}
        \|\sum_{i=0}^{k}M^i\|_2 &= \|\sum_{i=0}^{k}P\cdot \text{diag}(\lambda_1^i, \lambda_2^i, \lambda_3^i)P^{-1}\|_2 = \|P\cdot \text{diag}\left(\sum_{i=0}^{k}\lambda_1^i, \sum_{i=0}^{k}\lambda_2^i, \sum_{i=0}^{k}\lambda_3^i\right)P^{-1}\|_2\\
        &\leq C_M\cdot \max_i \frac{1}{1-\lambda_i} < \frac{3C_M}{2\alpha\mu},
    \end{aligned}
    \end{align}
    where the last inequality uses the upper bound of the eigenvalues. For \eqref{ineq: quadratic_conv} we have
    \begin{align*}
        &\max\left(\frac{1}{n}\mathbb{E}\left[\|X_k - x^*\mathbf{1}^{\top}\|^2\right], \frac{1}{n}\mathbb{E}\left[\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2\right]\right) \leq \frac{2}{n}\mathbb{E}\left[\|X_k -\bar{x}_k\mathbf{1}^{\top}\|^2 + n\|\bar{x}_k - x^*\|^2\right]\leq 2\sqrt{2}\|\Gamma_k\| \\
        \leq &2\sqrt{2}\|M^k\Gamma_0 + \sum_{i=0}^{k-1}M^ic\|\leq 2\sqrt{2}(\|M^k\|_2\|\Gamma_0\| + \|\sum_{i=1}^{k-1}M^i\|_2\|c\|) \\
        \leq &2\sqrt{2}C_M\left(1-\frac{2\alpha\mu}{3}\right)^k\|\Gamma_0\| + 2\sqrt{2}\cdot\frac{3C_M}{2\alpha\mu}\|c\| \\
        \leq & 2\sqrt{2}C_M\left(1-\frac{2\alpha\mu}{3}\right)^k(\mathbb{E}\left[\|\bar{x}_0 - x^*\|^2\right] + \mathbb{E}\left[\frac{\|X_0-\bar{x}_0\mathbf{1}^{\top}\|^2}{n}\right] + \mathbb{E}\left[\frac{\|S_0 - \bar{s}_0\mathbf{1}^{\top}\|^2}{n}\right]) + \frac{3\sqrt{2}C_M\|c\|}{\alpha\mu} \\
        \leq &3C_M\left(1-\frac{2\alpha\mu}{3}\right)^k\left(\mathbb{E}\left[\|\bar{x}_0 - x^*\|^2\right] + \mathbb{E}\left[\frac{\|X_0\|^2 + \|S_0\|^2}{n}\right]\right) + \frac{5C_M\|c\|}{\alpha\mu},
    \end{align*}
    where the fifth inequality uses \eqref{ineq: Mk} and \eqref{ineq: M_sum}, and the seventh inequality uses the fact that $\|X_0-\bar{x}_0\mathbf{1}^{\top}\| = \|X_0\left(I - \frac{\mathbf{1}\mathbf{1}^{\top}}{n}\right)\|\leq \|X_0\|$ (same for $S_0$). \eqref{ineq: bdd_2_m} can be viewed as a corollary of the above inequality by noticing that
    \begin{align*}
        &\frac{1}{n}\mathbb{E}\left[\|X_k\|^2\right]\leq \frac{2}{n}\mathbb{E}\left[\|X_k - x^*\mathbf{1}^{\top}\|^2 + n\|x^*\|^2\right] \\
        \leq &6C_M\left(1-\frac{2\alpha\mu}{3}\right)^k\left(\mathbb{E}\left[\|\bar{x}_0 - x^*\|^2\right] + \mathbb{E}\left[\frac{\|X_0\|^2 + \|S_0\|^2}{n}\right]\right) + \frac{10C_M\|c\|}{\alpha\mu} + 2\|x^*\|^2.
    \end{align*}

\begin{aligned}
            &\mathbb{E}\left[\|A_{i,k}\|^2\right] = \mathbb{E}\left[\|A_{i,k}-A_i\|^2\right] + \|A_i\|_2^2\leq \sigma_1^2 + L^2 = \tilde{\sigma}_1^2,\\
            &\mathbb{E}\left[\|b_{i,k}\|^2\right] = \mathbb{E}\left[\|b_{i,k}-b_i\|^2\right] + \|b_i\|^2 \leq \sigma_2^2 + \max_i\|b_i\|^2 = \tilde{\sigma}_2^2.
        \end{aligned}

\begin{aligned}
            &\|X_{k+1} - \bar{x}_{k+1}\mathbf{1}^{\top}\|^2 = \|X_kW - \bar{x}_k\mathbf{1}^{\top} - \alpha (S_k - \bar{s}_k\mathbf{1}^{\top})\|^2\\
        \leq &\left(1 + \frac{1-\rho^2}{2\rho^2}\right)\rho^2\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2 + \left(1 + \frac{2\rho^2}{1-\rho^2}\right)\alpha^2\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2.
        \end{aligned}

\begin{aligned}
            & \|S_{k+1} - \bar{s}_{k+1}\mathbf{1}^{\top}\|^2 = \|S_kW - \bar{s}_k\mathbf{1}^{\top} + V_{k+1} - V_k - \bar{v}_{k+1}\mathbf{1}^{\top} + \bar{v}_k\mathbf{1}^{\top}\|^2 \\
        \leq &\left(1 + \frac{1-\rho^2}{2\rho^2}\right)\|S_k - \bar{s}_k\mathbf{1}^{\top}\|^2 + \left(1 + \frac{2\rho^2}{1-\rho^2}\right)\|\left(V_{k+1}-V_k\right)\left(I - \frac{\mathbf{1}\mathbf{1}^{\top}}{n}\right)\|^2 \\
        = &\frac{1+\rho^2}{2}\|S_k - \bar{s}_k\mathbf{1}^{\top}\|^2 + \frac{1+\rho^2}{1-\rho^2}\|V_{k+1} - V_k\|^2.
        \end{aligned}

\begin{aligned}
            &\frac{1}{n}\mathbb{E}\left[\|S_{k+1} - \bar{s}_{k+1}\mathbf{1}^{\top}\|^2\right]\\
            \leq &\frac{1+\rho^2}{2n}\|S_k - \bar{s}_k\mathbf{1}^{\top}\|^2 + \frac{1+\rho^2}{1-\rho^2}
            \left(C_1\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + C_2\mathbb{E}\left[\frac{\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2}{n}\right] + \alpha^2C_3\mathbb{E}\left[\frac{\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2}{n}\right] + C_4\right) \\
            \leq &\frac{1+\rho^2}{1-\rho^2}C_1\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \frac{1+\rho^2}{1-\rho^2}C_2\mathbb{E}\left[\frac{\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2}{n}\right] + \left(\frac{1+\rho^2}{2} + \frac{1+\rho^2}{1-\rho^2}C_3\alpha^2\right)\mathbb{E}\left[\frac{\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2}{n}\right] +\frac{1+\rho^2}{1-\rho^2}C_4.

        \end{aligned}

\begin{aligned}
        \|\sum_{i=0}^{k}M^i\|_2 &= \|\sum_{i=0}^{k}P\cdot \text{diag}(\lambda_1^i, \lambda_2^i, \lambda_3^i)P^{-1}\|_2 = \|P\cdot \text{diag}\left(\sum_{i=0}^{k}\lambda_1^i, \sum_{i=0}^{k}\lambda_2^i, \sum_{i=0}^{k}\lambda_3^i\right)P^{-1}\|_2\\
        &\leq C_M\cdot \max_i \frac{1}{1-\lambda_i} < \frac{3C_M}{2\alpha\mu},
    \end{aligned}

\noindent{\bf Remark:} 
\begin{itemize}
    \item Lemma~\ref{lem: dsgd_quadratic} characterizes convergence results of decentralized stochastic gradient descent with gradient tracking on strongly convex quadratic functions. Moreover, it also indicates that the second moment of $X_k$ can be bounded by using \eqref{ineq: bdd_2_m}, which will be used in proving the boundedness of second moment of $Z_t^{(k)}$ of our HIGP oracle.

    \item If we consider the same updates under the deterministic setting, then $\sigma_1 = \sigma_2 = 0$ and thus $\|c\|= 0$ by definition, which indicates the constant term in \eqref{ineq: quadratic_conv} vanishes (i.e., linear convergence). We will utilize this important observation in the next lemma.

Suppose Assumptions \ref{assump: lip_convexity}, \ref{assump: W} and \ref{assump: stoc_derivatives} hold. In Algorithm \ref{algo: HIGP_oracle} define
    \begin{align*}
        &C_1 = 9\sigma_{g,2}^2 + 6\gamma^2(\sigma_{g,2}^2 + L_{g,1}^2) + \frac{18\gamma^2\sigma_{g,2}^2(\sigma_{g,2}^2 + L_{g,1}^2)}{n},\\
        &C_2 = 12(\sigma_{g,2}^2 + L_{g,1}^2) + 9\sigma_{g,2}^2 + 12\gamma^2L_{g,1}^2(\sigma_{g,2}^2 + L_{g,1}^2)  + \frac{18\gamma^2\sigma_{g,2}^2(\sigma_{g,2}^2 + L_{g,1}^2)}{n}, \\
        &C_3 = 6\rho^2(\sigma_{g,2}^2 + L_{g,1}^2),\ C_4 = 2\sigma_{f}^2 + \frac{6\gamma^2\sigma_{f}^2(\sigma_{g,2}^2 + L_{g,1}^2)}{n} + (9\sigma_{g,2}^2 + \frac{18\gamma^2\sigma_{g,2}^2(\sigma_{g,2}^2 + L_{g,1}^2)}{n})\|x^*\|^2, \\
