            \leq &\frac{1+\rho^2}{2n}\|S_k - \bar{s}_k\mathbf{1}^{\top}\|^2 + \frac{1+\rho^2}{1-\rho^2}
            \left(C_1\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + C_2\mathbb{E}\left[\frac{\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2}{n}\right] + \alpha^2C_3\mathbb{E}\left[\frac{\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2}{n}\right] + C_4\right) \\
            \leq &\frac{1+\rho^2}{1-\rho^2}C_1\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \frac{1+\rho^2}{1-\rho^2}C_2\mathbb{E}\left[\frac{\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2}{n}\right] + \left(\frac{1+\rho^2}{2} + \frac{1+\rho^2}{1-\rho^2}C_3\alpha^2\right)\mathbb{E}\left[\frac{\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2}{n}\right] +\frac{1+\rho^2}{1-\rho^2}C_4.

        \end{aligned}
    \end{equation}

On the other hand, observe that 
    \begin{align} \begin{aligned}
        \|\sum_{i=0}^{k}M^i\|_2 &= \|\sum_{i=0}^{k}P\cdot \text{diag}(\lambda_1^i, \lambda_2^i, \lambda_3^i)P^{-1}\|_2 = \|P\cdot \text{diag}\left(\sum_{i=0}^{k}\lambda_1^i, \sum_{i=0}^{k}\lambda_2^i, \sum_{i=0}^{k}\lambda_3^i\right)P^{-1}\|_2\\
        &\leq C_M\cdot \max_i \frac{1}{1-\lambda_i} < \frac{3C_M}{2\alpha\mu},
    \end{aligned}
    \end{align}
    where the last inequality uses the upper bound of the eigenvalues.

\eqref{ineq: bdd_2_m} can be viewed as a corollary of the above inequality by noticing that
    \begin{align*}
        &\frac{1}{n}\mathbb{E}\left[\|X_k\|^2\right]\leq \frac{2}{n}\mathbb{E}\left[\|X_k - x^*\mathbf{1}^{\top}\|^2 + n\|x^*\|^2\right] \\
        \leq &6C_M\left(1-\frac{2\alpha\mu}{3}\right)^k\left(\mathbb{E}\left[\|\bar{x}_0 - x^*\|^2\right] + \mathbb{E}\left[\frac{\|X_0\|^2 + \|S_0\|^2}{n}\right]\right) + \frac{10C_M\|c\|}{\alpha\mu} + 2\|x^*\|^2.
    \end{align*}

Assumption \ref{assump: lip_convexity} also indicates that 
    \begin{align*}
        \mu_g I\preceq \nabla_y^2g_i(x_{i,k},y_{i,k}^{(T)})\preceq L_{g,1} I,\ \|\nabla_yf_i(x_{i,k},y_{i,k}^{(T)})\|\leq L_{f,0}.
    \end{align*}

Hence we know by \eqref{ineq: bdd_2_m},
    \begin{align*}
        &\mathbb{E}\left[\|\bar{z}_t^{(k)}\|^2|\mathcal{F}_k\right]\leq \frac{1}{n}\mathbb{E}\left[\|Z_t^{(k)}\|^2|\mathcal{F}_k\right]\leq 6C_M\left(1-\frac{2\gamma\mu_g}{3}\right)^k\left(\frac{L_{f,0}^2}{\mu_g^2} + \sigma_{f}^2 + L_{f,0}^2\right) + \frac{10C_M\|c\|}{\gamma\mu_g} + \frac{2L_{f,0}^2}{\mu_g^2}\leq \sigma_z^2,
    \end{align*}



    which proves \eqref{ineq: z_bdd_2_m}.

To prove \eqref{ineq: z_exp_cons}, we notice that in expectation, the updates can be written as
    \begin{align*}
        &\mathbb{E}\left[z_{i,t+1}^{(k)}|\mathcal{F}_k\right] = \sum_{j=1}^{n}w_{ij}\mathbb{E}\left[z_{j,t}^{(k)}|\mathcal{F}_k\right] - \gamma \mathbb{E}\left[d_{i,t}^{(k)}|\mathcal{F}_k\right],\  Z_0^{(k)} = 0,\\
        &\mathbb{E}\left[d_{i,t+1}^{(k)}|\mathcal{F}_k\right] =\sum_{i=1}^{n}w_{ij}\mathbb{E}\left[d_{j,t}^{(k)}|\mathcal{F}_k\right] + \mathbb{E}\left[s_{i,t+1}^{(k)}|\mathcal{F}_k\right] - \mathbb{E}\left[s_{i,t}^{(k)}|\mathcal{F}_k\right], \\
        &\mathbb{E}\left[s_{i,t}^{(k)}|\mathcal{F}_k\right] = \nabla_y^2g_i(x_{i,k},y_{i,k}^{(T)})\mathbb{E}\left[z_{i,t}^{(k)}|\mathcal{F}_k\right]- \nabla_yf_i(x_{i,k},y_{i,k}^{(T)}).
    \end{align*}

Note that the inner and outer loop updates satisfy
    \begin{align*}
        &\bar{x}_{k+1} = \bar{x}_k - \alpha_k \bar{r}_k,\ X_{k+1} - \bar{x}_{k+1}\mathbf{1}^{\top} = X_kW - \bar{x}_k\mathbf{1}^{\top} - \alpha_k(R_k - \bar{r}_k\mathbf{1}^{\top}), \\
        &\bar{y}_k^{(t+1)} = \bar{y}_k^{(t)} - \beta_k\bar{v}_k^{(t)},\ Y_{k}^{(t+1)} - \bar{y}_k^{(t+1)} = Y_k^{(t)}W - \bar{y}_k^{(t)}\mathbf{1}^{\top} - \beta_k(V_k^{(t)} - \bar{v}_k^{(t)}\mathbf{1}^{\top}),
