            &\frac{1}{n}\mathbb{E}\left[\|Y_{k}^{(t+1)} - \bar{y}_{k}^{(t+1)}\mathbf{1}^{\top}\|^2\right] \\
        \leq &\left[\frac{(1+\rho^2)}{2} + \beta_k^2\frac{1+\rho^2}{1-\rho^2}\cdot 6L_{g,1}^2 \right]\cdot\frac{1}{n}\mathbb{E}\left[\|Y_k^{(t)} - \bar{y}_k^{(t)}\mathbf{1}^{\top}\|^2\right] + \beta_k^2\frac{1+\rho^2}{1-\rho^2}(2\sigma_{g,1}^2 + 6L_{g,1}^2\sigma_x^2\tilde{\alpha}_k^2 + 3\delta^2) \\
        \leq &\left(\frac{3+\rho^2}{4}\right)^{t+1}\cdot\frac{1}{n}\mathbb{E}\left[\|Y_k^{(0)} - \bar{y}_k^{(0)}\mathbf{1}^{\top}\|^2\right] + \beta_k^2\frac{1+\rho^2}{1-\rho^2}(2\sigma_{g,1}^2 + 6L_{g,1}^2\sigma_x^2\tilde{\alpha}_k^2 + 3\delta^2)\sum_{l=0}^{t}\left(\frac{3+\rho^2}{4}\right)^i \\
        \leq &\left(\frac{3+\rho^2}{4}\right)^{t+1}\cdot\frac{1}{n}\mathbb{E}\left[\|Y_k^{(0)} - \bar{y}_k^{(0)}\mathbf{1}^{\top}\|^2\right] + (t+1)\beta_k^2\frac{1+\rho^2}{1-\rho^2}(2\sigma_{g,1}^2 + 6L_{g,1}^2\sigma_x^2\tilde{\alpha}_k^2 + 3\delta^2),
        \end{aligned}
    \end{equation}
    where the second inequality uses Lemma \ref{lem: useful_ineq} and \eqref{ineq: beta_condition}.

Observe that we also have
    \begin{equation}
        \begin{aligned}
            &\mathbb{E}\left[\|\bar{y}_{k+1}^{(0)}-y_{k}^*\|^2\right] = \mathbb{E}\left[\|\bar{y}_{k}^{(T)}-y_{k}^*\|^2\right] \leq  (1-\beta_k\mu_g)^{T}\mathbb{E}\left[\|\bar{y}_k^{(0)}-y_k^*\|^2\right] + C_{k,T} \\
            \leq & (1-\beta_k\mu_g)^{T}\mathbb{E}\left[\left(1+\frac{\beta_k\mu_g}{2}\right)\|\bar{y}_k^{(0)}-y_{k-1}^*\|^2 + \left(1+\frac{2}{\beta_k\mu_g}\right)\|y_{k-1}^* - y_k^*\|^2\right] + C_{k,T}\\
            \leq & \left(1+\frac{\beta_k\mu_g}{2}\right)(1-\beta_k\mu_g)^{T}\mathbb{E}\left[\|\bar{y}_k^{(0)}-y_{k-1}^*\|^2\right] + \left(\frac{2\alpha_{k-1}^2}{\beta_k\mu_g}+\alpha_{k-1}^2\right)L_{y^*}^2\mathbb{E}\left[\|\bar{r}_{k-1}\|^2\right] + C_{k,T}\\
            \leq & \left(1-\frac{\beta_k\mu_g}{2}\right)\mathbb{E}\left[\|\bar{y}_k^{(0)}-y_{k-1}^*\|^2\right] + \left(\frac{2\alpha_{k-1}^2}{\beta_k\mu_g}+\alpha_{k-1}^2\right)L_{y^*}^2\mathbb{E}\left[\|\bar{r}_{k-1}\|^2\right] + C_{k,T},
        \end{aligned}
    \end{equation}
    where the third inequality holds since $(1+\frac{a}{2})(1-a)^T\leq (1-\frac{a}{2})$ for any $a>0$ and $T\geq 1$, and $y^*(x)$ is $L_{y^*}$-smooth.

Taking summation on both sides, we have
    \begin{align*}
        \frac{\mu_g}{2}\sum_{k=1}^{K}\beta_k\mathbb{E}\left[\|\bar{y}_k^{(0)} - y_{k-1}^*\|^2\right]\leq \mathbb{E}\left[\|\bar{y}_{1}^{(0)}-y_{0}^*\|^2\right] + L_{y^*}^2\sum_{k=1}^{K}\left(\frac{2\alpha_{k-1}^2}{\beta_k\mu_g}+\alpha_{k-1}^2\right)\mathbb{E}\left[\|\bar{r}_{k-1}\|^2\right] + \sum_{k=1}^{K}C_{k,T}.
    \end{align*}

We know
    \begin{align*}
