    for sufficiently large $K$.

Define
\begin{align*}
    y_k^* &= y^*(\bar{x}_k), \\
    z_{*}^{(k)} &= \left(\sum_{i=1}^{n}\nabla_y^2g_i(\bar{x}_k,y_k^*)\right)^{-1}\left(\sum_{i=1}^{n}\nabla_y f_i(\bar{x}_k, y_k^*)\right).
\end{align*}
To bound the hypergradient estimation error, a rough analysis (see Lemma \ref{lem: last}) shows that $\mathbb{E}\left[\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2\right] =$
\[
    \begin{aligned}
        &\resizebox{\hsize}{!}{$\mathcal{O}\Big(\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2 + \|Y_k^{(T)} - \bar{y}_k^{(T)}\mathbf{1}^{\top}\|^2 + \|\bar{y}_k^{(T)} - y_k^*\|^2\right]$} \\ 
        &\resizebox{\hsize}{!}{$+ \mathbb{E}\left[\|\mathbb{E}\left[z_{i,N}^{(k)} - \bar{z}_{N}^{(k)}|\mathcal{F}_k\right]\|^2 + \|\mathbb{E}\left[\bar{z}_N^{(k)}|\mathcal{F}_k\right] - z_*^{(k)}\|^2\right]\Big),$}
    \end{aligned}
\]
where the first two terms on the right hand side denote the consensus error among agents, and can be bounded via techniques in decentralized optimization (Lemma \ref{lem: XY_cons}). The third term represents the inner loop estimation error, which can be bounded by considering its decrease as $k$ increases (Lemma \ref{lem: y_error}). Our novelty lies in bounding the last two terms -- the consensus and convergence analysis of the HIGP oracle. Observe that
by setting 
\[
    \resizebox{\hsize}{!}{$\dot z_{i,t}^{(k)} = \mathbb{E}\left[z_{i,t}^{(k)}|\mathcal{F}_k\right], \dot d_{j,t}^{(k)} =\mathbb{E}\left[d_{j,t}^{(k)}|\mathcal{F}_k\right], \dot s_{i,t}^{(k)} = \mathbb{E}\left[s_{i,t}^{(k)}|\mathcal{F}_k\right],$}
\]
we know from Algorithm \ref{algo: HIGP_oracle}
\begin{align*}
    &\dot z_{i,t+1}^{(k)} = \sum_{j=1}^{n}w_{ij}\dot z_{j,t}^{(k)} - \gamma \dot d_{i,t}^{(k)},\  Z_0^{(k)} = 0,\\
    &\dot d_{i,t+1}^{(k)} =\sum_{i=1}^{n}w_{ij}\dot d_{j,t}^{(k)} + \dot s_{i,t+1}^{(k)} - \dot s_{i,t}^{(k)}, \\
    &\dot s_{i,t}^{(k)} = \nabla_y^2g_i(x_{i,k},y_{i,k}^{(T)})\dot z_{i,t}^{(k)}- \nabla_yf_i(x_{i,k},y_{i,k}^{(T)}),
\end{align*}
which is exactly a deterministic gradient descent scheme with gradient tracking on a strongly convex and smooth quadratic function. Hence the linear convergence results in gradient tracking methods can be applied, and this also explains why $\gamma$ can be chosen as a constant that is independent of $K$. Mathematically, in Lemmas \ref{lem: higp_main} and \ref{lem: last} we explicitly characterize the error and eventually obtain the final convergence result in Theorem \ref{thm: main}.

It can then be shown that by appropriately choosing parameters (see Lemma \ref{lem: r_bar_sum} and \ref{lem: r_and_grad} for details), we obtain
\begin{align*}
    &\frac{1}{K}\sum_{k=0}^{K}\mathbb{E}\left[\|\bar{r}_k\|^2 + \|\bar{r}_k - \nabla\Phi(\bar{x}_k)\|^2\right] \\
    = &\mathcal{O}\left(\frac{1}{\sqrt{K}} + \frac{1}{K}\sum_{k=0}^{K}\mathbb{E}\left[\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2\right]\right),
\end{align*}
which implies that it suffices to bound the hypergradient estimation error, namely, the second term on the right hand side of the above equality.

Define
\begin{align*}
    y_k^* &= y^*(\bar{x}_k), \\
    z_{*}^{(k)} &= \left(\sum_{i=1}^{n}\nabla_y^2g_i(\bar{x}_k,y_k^*)\right)^{-1}\left(\sum_{i=1}^{n}\nabla_y f_i(\bar{x}_k, y_k^*)\right).
\end{align*}

To bound the hypergradient estimation error, a rough analysis (see Lemma \ref{lem: last}) shows that $\mathbb{E}\left[\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2\right] =$
\[
    \begin{aligned}
        &\resizebox{\hsize}{!}{$\mathcal{O}\Big(\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2 + \|Y_k^{(T)} - \bar{y}_k^{(T)}\mathbf{1}^{\top}\|^2 + \|\bar{y}_k^{(T)} - y_k^*\|^2\right]$} \\ 
        &\resizebox{\hsize}{!}{$+ \mathbb{E}\left[\|\mathbb{E}\left[z_{i,N}^{(k)} - \bar{z}_{N}^{(k)}|\mathcal{F}_k\right]\|^2 + \|\mathbb{E}\left[\bar{z}_N^{(k)}|\mathcal{F}_k\right] - z_*^{(k)}\|^2\right]\Big),$}
    \end{aligned}
\]
where the first two terms on the right hand side denote the consensus error among agents, and can be bounded via techniques in decentralized optimization (Lemma \ref{lem: XY_cons}).

Our novelty lies in bounding the last two terms -- the consensus and convergence analysis of the HIGP oracle. Observe that
by setting 
\[
    \resizebox{\hsize}{!}{$\dot z_{i,t}^{(k)} = \mathbb{E}\left[z_{i,t}^{(k)}|\mathcal{F}_k\right], \dot d_{j,t}^{(k)} =\mathbb{E}\left[d_{j,t}^{(k)}|\mathcal{F}_k\right], \dot s_{i,t}^{(k)} = \mathbb{E}\left[s_{i,t}^{(k)}|\mathcal{F}_k\right],$}
\]
we know from Algorithm \ref{algo: HIGP_oracle}
\begin{align*}
    &\dot z_{i,t+1}^{(k)} = \sum_{j=1}^{n}w_{ij}\dot z_{j,t}^{(k)} - \gamma \dot d_{i,t}^{(k)},\  Z_0^{(k)} = 0,\\
    &\dot d_{i,t+1}^{(k)} =\sum_{i=1}^{n}w_{ij}\dot d_{j,t}^{(k)} + \dot s_{i,t+1}^{(k)} - \dot s_{i,t}^{(k)}, \\
    &\dot s_{i,t}^{(k)} = \nabla_y^2g_i(x_{i,k},y_{i,k}^{(T)})\dot z_{i,t}^{(k)}- \nabla_yf_i(x_{i,k},y_{i,k}^{(T)}),
\end{align*}
which is exactly a deterministic gradient descent scheme with gradient tracking on a strongly convex and smooth quadratic function.
